    icons: ICON_SIZES.map((size) => ({
      src: `${APP_BASE}icon-${size}.png`,
      sizes: `${size}x${size}`,
      type: "image/png",
      purpose: "any maskable",
    })),
  });
  writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);

