        editor.execCommand("FormatBlock", false, `h${level}`),
      );
    }

    const sizeFormats: Record<PantokenFontSize, string> = {
      xs: "pantoken-size-xs",
      sm: "pantoken-size-sm",
      md: "pantoken-size-md",
      lg: "pantoken-size-lg",
      xl: "pantoken-size-xl",
